from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    initial_bounds = {
        name: [minimum, maximum]
        for name, (minimum, maximum) in roots.items()
    }

    def dependency_is_active(dependency):
        feature = dependency.get("feature")
        return not feature or feature in features

    def is_acyclic(selected_rows):
        graph = {}
        for name, row in selected_rows.items():
            graph[name] = [
                dependency["name"]
                for dependency in row.get("deps", [])
                if dependency_is_active(dependency)
            ]

        state = {}

        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, []):
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, selected_rows, bounds):
        nonlocal best_vector, best_versions

        for name, version in assigned.items():
            if name in bounds:
                minimum, maximum = bounds[name]
                if not minimum <= version <= maximum:
                    return

        pending = [name for name in bounds if name not in assigned]
        if not pending:
            if not is_acyclic(selected_rows):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = min(pending)
        minimum, maximum = bounds[name]
        forbidden = blocked.get(name, ())
        candidates = sorted(
            (
                row for row in packages.get(name, [])
                if minimum <= row["version"] <= maximum
                and row["version"] not in forbidden
                and (name not in pins or row["version"] == pins[name])
            ),
            key=lambda row: row["version"],
            reverse=True,
        )

        for row in candidates:
            version = row["version"]
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_bounds = {key: value[:] for key, value in bounds.items()}
            valid = True

            for dependency in row.get("deps", []):
                if not dependency_is_active(dependency):
                    continue
                dep_name = dependency["name"]
                dep_minimum = dependency["min"]
                dep_maximum = dependency["max"]
                if dep_name in next_bounds:
                    dep_bounds = next_bounds[dep_name]
                    dep_bounds[0] = max(dep_bounds[0], dep_minimum)
                    dep_bounds[1] = min(dep_bounds[1], dep_maximum)
                else:
                    next_bounds[dep_name] = [dep_minimum, dep_maximum]

                dep_bounds = next_bounds[dep_name]
                if dep_bounds[0] > dep_bounds[1]:
                    valid = False
                    break
                if dep_name in next_assigned and not (
                    dep_bounds[0] <= next_assigned[dep_name] <= dep_bounds[1]
                ):
                    valid = False
                    break

            if valid:
                search(next_assigned, next_rows, next_bounds)

    search({}, {}, initial_bounds)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
